mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("[100, -5, 100, 20]","2,0,2,1"),
        ("[5, 5, -1]","1,1,0"),
        ("[1,2,3,4,5,6,7]","0,1,2,3,4,5,6"),
        ("[3,3,3,3,3,3,3]","0,0,0,0,0,0,0"),
        ("[8,7,6,5,4,3,2]","6,5,4,3,2,1,0"),
        ("  \n[100, -5, 100, 20]\n  ","2,0,2,1"),
        ("\n[8,7,6,5,4,3,2]\n","6,5,4,3,2,1,0")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS coordinate-compression");
}
